# Tidy human-readable number spacing without changing IDs, units, URLs or exact source titles.
import re
human_keys={'label','title','detail','text','body','action','short','when','why','clinical','description','message','recommendation','explanation','notes','note','source_page','summary','schedule_summary','duration_text','source_schedule_interval_label','source_duration_note','source_basis','population','comparison','applicability','result_text','interpretation','trial','qualitative_result','metric','dose','timing','administration_text'}
list_keys={'additional_support','eligibility','exclusions','monitoring','dose_modifications','key_points','baseline','before_each_cycle','ongoing','administration','access','clinical_notes','limitations','support_summary','important_cautions','eligibility_orientation'}
def tidytext(t):
 t=re.sub(r'(\d)(mg|mL|mL/min|mmol|micromol|hours|hour|days|day|minutes|minutes|cycles|Gy|months)(?![A-Za-z])',r'\1 \2',t)
 t=re.sub(r'\b(Days?|Table|Grade|grade|CrCl|ECOG|NCCP|cycles|cycles|etoposide|cisplatin|carboplatin|and|to|below|above)(?=\d)',r'\1 ',t)
 t=re.sub(r'(?<=[A-Za-z])(?=\d{5}\b)',' ',t)
 return t.replace('in1L','in 1 L').replace('per1','per 1').replace('per2','per 2').replace('V8','V8')
def tidy(x,key=''):
 if isinstance(x,dict):return {k:tidy(v,k) for k,v in x.items()}
 if isinstance(x,list):return [tidy(v,key) for v in x]
 if isinstance(x,str) and (key in human_keys or key in list_keys):return tidytext(x)
 return x
for fn in ['authoring.json','proposed/00456-protocol.json','proposed/00561-protocol.json','proposed/radiotherapy-consent-profile.json']:
 q=B/fn;write(q,tidy(json.loads(q.read_text())))
